pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // setup: two users, A and B
        address A = address(0x1);
        address B = address(0x2);

        // give both users some ether
        vm.deal(A, 10 ether);
        vm.deal(B, 10 ether);

        // A puts 1 ether with unlockTime = 1 (block.timestamp starts at 1 in forge)
        vm.prank(A);
        c.Put{value: 1 ether}(1);

        // B puts 1 ether with unlockTime = 100 (much later)
        vm.prank(B);
        c.Put{value: 1 ether}(100);

        // advance time far beyond both unlockTimes
        vm.warp(200);

        // In reference: A's balance = 1 ether, unlockTime = max(1, block.timestamp at time of call)=1 => 1 < 200, so Collect should work
        // In buggy: A's unlockTime = 0 (always 0) so also < 200, still ok
        // But the difference: after referencing, buggy allows Collect from A even when B's unlockTime not met?
        // Actually the key divergence: in reference, A's unlockTime = block.timestamp (since _unlockTime=1 <= block.timestamp=1 at call) => 1,
        // B's unlockTime = 100. After warp(200), both can Collect.
        // In buggy, A's unlockTime = 0, B's unlockTime = 100. Same.
        // The real divergence is that in reference, if A calls Put(1) when block.timestamp is 200, unlockTime becomes max(1,200)=200;
        // in buggy, it's 0 regardless. So need scenario: user puts with _unlockTime in future so reference sets unlockTime to that future,
        // buggy sets to 0, allowing earlier withdrawal.
        // Let's redo:
        // Scenario: A calls Put(100) with 1 ether at time 1, so ref sets unlockTime = 100, buggy sets = 0.
        // B calls Put(50) with 1 ether at time 1.
        // Warp to time 80: ref: A cannot collect (unlockTime 100 > 80), B can (50 < 80).
        // Buggy: A can collect (unlockTime 0 < 80) so A can drain B's funds? Actually each has own balance.
        // But the test must break assertion. Let's assert that A.collect fails in reference but succeeds in buggy.
        // Clean slate:
        c = new C(address(this));
        vm.deal(A, 10 ether);
        vm.deal(B, 10 ether);
        vm.warp(1);
        vm.prank(A);
        c.Put{value: 1 ether}(100);
        vm.prank(B);
        c.Put{value: 1 ether}(50);
        vm.warp(80);
        // Now A tries to collect 1 ether
        vm.prank(A);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, 1 ether));
        if (ok) {
            // if success, check A's balance decreased
            uint balAfter = c.Acc(A).balance;
            assertTrue(balAfter == 0 ether);
        } else {
            // if revert, A's balance unchanged
            uint balAfter = c.Acc(A).balance;
            assertTrue(balAfter == 1 ether);
        }
        // The above is fragile. Better: assert that in reference A's Collect call should revert (unlockTime 100 > 80)
        // In buggy it should succeed (unlockTime 0 < 80) and thus A's balance becomes 0.
        // So we catch revert and assert the opposite.
        // Let's do try/catch:
        vm.prank(A);
        try c.Collect(1 ether) {
            // succeeded: buggy version
            // in reference this shouldn't happen, but test fails if assertion fails
            // We'll assert that in the reference this call would revert - but we can't know runtime.
            // Actually we just assert a fact that diverges: after call, A's balance in reference is 1 ether, in buggy is 0.
            // Since we are running on one version at a time, we can't check both. But we know the expected behavior per version.
            // The test must pass on reference, fail on buggy. So on reference, this try should catch revert, on buggy it should succeed.
            // So after the call, if we are on buggy, balance = 0; if on reference, revert is caught.
            // To make assertion fail on buggy, assert that balance is 1 ether? But after buggy success, balance is 0.
            // So assert True(balance == 1 ether) would fail on buggy.
            // But we need to handle that on reference, the call reverts and the catch block executes.
            // So let's structure:
            uint bal = c.Acc(A).balance;
            assertTrue(bal == 0 ether);
        } catch {
            uint bal = c.Acc(A).balance;
            assertTrue(bal == 1 ether);
        }
        // This passes on reference (catch -> bal=1 -> assertTrue(1==1) ok) but fails on buggy?
        // On buggy, try succeeds -> bal=0 -> assertTrue(0==0) ok -> should also pass? That's not fail.
        // Need to make assertion different for the two versions.
        // Better approach: assert after the call that the balance equals a specific value that matches reference but not buggy.
        // Since we know the call behavior, we can use a single assertion that is true for reference, false for buggy.
        // In reference, A's Collect reverts because unlockTime 100 > 80, so balance stays 1 ether.
        // In buggy, A's Collect succeeds and balance becomes 0.
        // So we can assert: after the call (regardless of revert), A's balance == 1 ether.
        // On reference, revert happens, balance = 1 ether => assertTrue(1==1) passes.
        // On buggy, success happens, balance = 0 ether => assertTrue(0==1) fails.
        // But we need to catch revert so the test doesn't abort.
        vm.prank(A);
        try c.Collect(1 ether) {
            // success: balance changed
        } catch {
            // revert: balance unchanged
        }
        uint balAfter = c.Acc(A).balance;
        assertTrue(balAfter == 1 ether);
    }
}

