import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up a concrete scenario: user puts 2 ether with unlockTime far in the future
        address user = address(0x1234);
        uint future = block.timestamp + 1000;

        // First Put sets unlockTime to future
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Put{value: 2 ether}(future);

        // Second Put via fallback (sends 0 ether, call data empty triggers fallback which calls Put(0))
        // In reference: unlockTime stays max(future, block.timestamp) = future (since future > now)
        // In bug: unlockTime = block.timestamp (overwrites future)
        vm.prank(user);
        (bool ok,) = address(c).call{value: 0 ether}("");

        // Now warp to current time + 100 (still before future but after bug's timestamp)
        vm.warp(block.timestamp + 100);

        // Try Collect(1 ether) - should revert in reference (unlockTime still future)
        // but succeed in bug (unlockTime set to earlier timestamp)
        vm.prank(user);
        bool success;
        try c.Collect{value: 0 ether}(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: Collect should revert (false), bug: Collect succeeds (true)
        // We assert false to catch the bug: assertTrue(success == false) fails on bug version
        assertTrue(success == false);
    }
}

